const $=selector=>document.querySelector(selector);
const $$=selector=>[...document.querySelectorAll(selector)];
function readLocal(key){const current=`redo_${key}`;let value=localStorage.getItem(current);if(value===null){value=localStorage.getItem(`olx${key[0].toUpperCase()}${key.slice(1)}`);if(value!==null)localStorage.setItem(current,value)}return value}
function writeLocal(key,value){localStorage.setItem(`redo_${key}`,value)}

const localArray=key=>{try{const value=JSON.parse(readLocal(key)||'[]');return Array.isArray(value)?value:[]}catch{return[]}};
const localListings=()=>localArray('listings');
let listings=sbClient?[]:[...localListings(),...seedListings];
let listingsLoading=!!sbClient;
let favorites=new Set(localArray('favorites'));
let localMessages=localArray('messages');
let user=null,activeCategory='all',query='',locationQuery='',priceLimit=0,favoritesOnly=false,showAll=false,activeChannel=null,currentConversationId=null;
let chatBackPushed=false,chatReturnTarget=null,chatContext=null;

function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function normalizeArea(value){return String(value??'').toLocaleLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').replace(/(.)\1+/g,'$1').replace(/kattapana/g,'kattappana').trim()}
function areaMatches(listingArea,selectedArea){const area=normalizeArea(listingArea),parts=String(selectedArea||'').split(',').map(normalizeArea).filter(Boolean);return !parts.length||parts.some(part=>area.includes(part)||part.includes(area))}
function safeImage(value){const url=String(value||'');return /^https:\/\//i.test(url)||/^data:image\/(png|jpeg|webp);base64,/i.test(url)?url:'https://images.unsplash.com/photo-1560393464-5c69a73c5770?auto=format&fit=crop&w=800&q=80'}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2800)}
function money(value){return Number(value)>0?'₹ '+Number(value).toLocaleString('en-IN'):'Contact for details'}
function isRealUser(){return !!user?.id&&user.id!=='local-demo'}
function stopLiveChat(){if(activeChannel&&sbClient)sbClient.removeChannel(activeChannel);activeChannel=null;currentConversationId=null}
function openModal(html,wide=false){stopLiveChat();$('#modalContent').innerHTML=html;$('.modal').classList.remove('settings-modal','chat-modal');$('.modal').classList.toggle('listing-modal',wide);$('#closeModal').onclick=closeModal;$('#modalBackdrop').classList.remove('hidden');document.body.style.overflow='hidden'}
function closeModal(){stopLiveChat();$('#modalBackdrop').classList.add('hidden');document.body.style.overflow='';$('.modal').classList.remove('listing-modal','settings-modal','chat-modal','welcome-auth-modal');$('#closeModal').hidden=false}
function handleChatBack(fromPopState=false){if(!chatBackPushed){closeModal();return}if(!fromPopState){history.back();return}chatBackPushed=false;const target=chatReturnTarget;if(target?.type==='inbox')messagesModal(target.role);else if(target?.listingId)listingModal(target.listingId);else closeModal()}
function showInfo(title,body){const pages={
  'About us':'redo helps neighbors pass useful things along. Browse community listings, ask sellers questions, and arrange a safe local handoff.',
  'About redo':'redo helps neighbors pass useful things along. Browse community listings, ask sellers questions, and arrange a safe local handoff.',
  Careers:'We are a small marketplace project. For now, use Contact to get in touch about contributing.',
  Contact:'For marketplace questions, contact the person who posted the relevant listing through its chat. For site support, add your support email to the footer before launch.',
  'Help & support':'Need help with an ad? Open My account → Manage my listings. For a buyer question, open the listing and choose Chat with seller.',
  'Safety tips':'Meet in a public place, inspect an item before paying, keep conversation on redo, and never share one-time codes or banking passwords. Report suspicious listings from the listing details.',
  Privacy:'Guests can save favorites on this device. Supabase stores listings, accounts, messages and synced favorites when connected. When Supabase is connected, account, listing, favorite, saved-search and message data are stored in your Supabase project. Add a reviewed privacy policy and contact address before public launch.',
  Terms:'Use redo to post accurate listings and communicate respectfully. Arrange exchanges directly and follow local laws. Add terms reviewed for your location before public launch.'
};const copy=pages[title]||body;openModal(`<span class="eyebrow">REDO MARKETPLACE</span><h2>${escapeHtml(title)}</h2><p>${escapeHtml(copy)}</p><button class="auth-button primary" id="infoClose">Close</button>`);$('#infoClose').onclick=closeModal}
function popularSearchesModal(){const terms=['iPhone','Sofa','Used car','Apartment','Camera','Books'];openModal(`<span class="eyebrow">POPULAR RIGHT NOW</span><h2>Popular searches</h2><p>Start with a popular search, then narrow results by category and place.</p><div class="popular-search-grid">${terms.map(term=>`<button type="button" data-popular-search="${escapeHtml(term)}">⌕ ${escapeHtml(term)}</button>`).join('')}</div><button class="auth-button" id="popularClose">Close</button>`);$$('[data-popular-search]').forEach(button=>button.onclick=()=>{$('#searchInput').value=button.dataset.popularSearch;closeModal();renderSearch()});$('#popularClose').onclick=closeModal}
function footerAction(page){if(page==='Categories'){$('.category-section').scrollIntoView({behavior:'smooth'});return}if(page==='Popular searches'){popularSearchesModal();return}if(page==='Nearby listings'){openLocation();return}if(page==='Contact'){openModal('<span class="eyebrow">CONTACT REDO</span><h2>How can we help?</h2><p>For a listing, open its chat to contact the seller. For account or site help, use your redo inbox and include the listing title or a screenshot.</p><div class="contact-action-grid"><button class="auth-button primary" id="contactMessages">Open messages</button><button class="auth-button" id="contactSafety">Safety tips</button></div>');$('#contactMessages').onclick=()=>messagesModal();$('#contactSafety').onclick=()=>showInfo('Safety tips');return}if(page==='Help & support'){openModal('<span class="eyebrow">HELP CENTRE</span><h2>What do you need?</h2><div class="help-action-list"><button id="helpListings"><b>Manage my listings</b><span>Edit, mark sold, or remove an ad.</span></button><button id="helpMessages"><b>Messages</b><span>Find your buyer or seller conversation.</span></button><button id="helpSafety"><b>Stay safe</b><span>Read marketplace safety guidance.</span></button></div>');$('#helpListings').onclick=()=>isRealUser()?myListingsModal():loginModal();$('#helpMessages').onclick=()=>messagesModal();$('#helpSafety').onclick=()=>showInfo('Safety tips');return}if(page==='Careers'){openModal('<span class="eyebrow">CAREERS AT REDO</span><h2>Build a more circular community.</h2><p>redo is an early marketplace project. There are no open roles listed yet. If you want to contribute, use Contact and tell us what you would like to build.</p><button class="auth-button primary" id="careerContact">Contact redo</button>');$('#careerContact').onclick=()=>footerAction('Contact');return}showInfo(page)}
async function shareRedo(){const share={title:'redo — Good things, found again',text:'Find thoughtful second-hand deals and give good things a new home.',url:location.origin+location.pathname};try{if(navigator.share)await navigator.share(share);else if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(share.url);toast('redo link copied.')}else showInfo('Share redo','Copy this page address to share redo with a friend.')}catch(error){if(error.name!=='AbortError')toast('Could not share redo.') }}
function authSetup(){openModal(`<span class="eyebrow">SUPABASE SETUP</span><h2>Connect real sign-in</h2><p>Add your project URL and publishable key to <b>config.js</b>. Then enable Google under Supabase Authentication providers.</p><p>See the setup checklist in README.md. Guests can browse without signing in; actions that contact sellers require a connected Google account.</p><button class="auth-button primary" id="authSetupClose">Got it</button>`);$('#authSetupClose').onclick=closeModal}
function renderCategories(){$('#categoryGrid').innerHTML=categories.map(([name,icon,photo])=>`<button class="category-card" data-category="${name}"><span class="category-icon"><img src="https://images.unsplash.com/${photo}?auto=format&fit=crop&w=320&q=78" alt="" loading="lazy"><span class="category-symbol" aria-hidden="true">${icon}</span></span><span>${document.documentElement.lang==='ml'?(malayalamLabels[name]||name):name}</span></button>`).join('');window.redoObserveReveal?.($$('#categoryGrid .category-card'))}
function renderListings(){
  if(listingsLoading){$('#resultsCount').textContent='Loading finds…';$('#emptyState').classList.add('hidden');$('#loadMore').classList.add('hidden');$('#listingGrid').innerHTML=Array.from({length:4},()=>'<div class="listing-skeleton" aria-hidden="true"><span></span><i></i><i></i></div>').join('');return}
  let items=listings.filter(x=>!['sold','removed'].includes(x.status)&&(activeCategory==='all'||x.category===activeCategory)&&(!query||`${x.title} ${x.category} ${x.area}`.toLowerCase().includes(query.toLowerCase()))&&(!locationQuery||areaMatches(x.area,locationQuery))&&(!priceLimit||Number(x.price)<=priceLimit)&&(!favoritesOnly||favorites.has(x.id)));
  const sort=$('#sortSelect')?.value||'newest';if(sort==='low')items.sort((a,b)=>Number(a.price)-Number(b.price));if(sort==='high')items.sort((a,b)=>Number(b.price)-Number(a.price));
  $('#resultsCount').textContent=`${items.length} finds`;
  $('#emptyState').classList.toggle('hidden',items.length>0);$('#loadMore').classList.toggle('hidden',items.length<=8||showAll);
  if(!showAll)items=items.slice(0,8);
  $('#listingGrid').innerHTML=items.map(x=>`<article class="listing-card ${$('#listView').classList.contains('active')?'list-card':''}" data-id="${escapeHtml(x.id)}"><img class="listing-image" src="${escapeHtml(safeImage(x.photo_url||x.img))}" alt="${escapeHtml(x.title)}" loading="lazy"><span class="badge-new">${String(x.id).startsWith('u')?'JUST LISTED':x.user_id?'JUST LISTED':'GOOD FIND'}</span><button class="fav-btn ${favorites.has(x.id)?'saved':''}" aria-label="Save listing" data-fav="${escapeHtml(x.id)}">${favorites.has(x.id)?'♥':'♡'}</button><div class="listing-info"><div class="listing-price">${money(x.price)}</div><div class="listing-title">${escapeHtml(x.title)}</div><div class="listing-desc">${escapeHtml(x.description||x.desc)}</div><div class="listing-meta"><span>${escapeHtml(x.area)}</span><span>${escapeHtml(x.time||'Recently')}</span></div></div></article>`).join('');window.redoObserveReveal?.($$('#listingGrid .listing-card'));
}
function setCategory(category){favoritesOnly=false;activeCategory=category||'all';$$('.filter-chip').forEach(b=>b.classList.toggle('active',(b.dataset.filter==='all'&&activeCategory==='all')||b.dataset.filter===activeCategory));renderListings();$('#latest').scrollIntoView({behavior:'smooth',block:'start'})}
function updateLocationLabel(value){const label=$('.location-select span:nth-child(2)');if(label)label.textContent=value||'Kerala'}
function loadGoogleMaps(){if(window.google?.maps?.Geocoder)return Promise.resolve();if(!GOOGLE_MAPS_API_KEY)return Promise.reject(new Error('Add a restricted Google Maps API key in config.js to find your city automatically. You can still type your area below.'));if(window.redoMapsPromise)return window.redoMapsPromise;window.redoMapsPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=`https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(GOOGLE_MAPS_API_KEY)}&v=weekly`;script.async=true;script.onload=()=>{if(window.google?.maps)resolve();else{window.redoMapsPromise=null;reject(new Error('Google Maps could not start. Check that Maps JavaScript API is enabled.'))}};script.onerror=()=>{window.redoMapsPromise=null;reject(new Error('Google Maps could not load. Check the API key and website restrictions.'))};document.head.appendChild(script)});return window.redoMapsPromise}
function findCityFromCoords(coords){return new Promise(async(resolve,reject)=>{try{await loadGoogleMaps();new google.maps.Geocoder().geocode({location:{lat:coords.latitude,lng:coords.longitude}},(results,status)=>{if(status!=='OK'||!results?.length){reject(new Error('Could not identify a nearby city. Enter it below instead.'));return}const components=results[0].address_components||[];const preferred=['locality','postal_town','administrative_area_level_2','sublocality_level_1'];const component=preferred.map(type=>components.find(item=>item.types.includes(type))).find(Boolean);const city=component?.long_name;if(!city){reject(new Error('Could not identify a nearby city. Enter it below instead.'));return}resolve(city)})}catch(error){reject(error)}})}
function applyLocation(value,label=value){locationQuery=value;updateLocationLabel(label);closeModal();renderListings();$('#latest').scrollIntoView({behavior:'smooth'});toast(`Showing finds around ${label}.`)}
const keralaPlaces={
  Alappuzha:['Alappuzha','Cherthala','Kayamkulam','Mavelikkara','Haripad'],
  Ernakulam:['Kochi','Aluva','Kalamassery','Thrippunithura','Perumbavoor','Muvattupuzha','North Paravur'],
  Idukki:['Thodupuzha','Munnar','Painavu','Kattappana','Nedumkandam'],
  Kannur:['Kannur','Thalassery','Payyannur','Mattannur','Taliparamba'],
  Kasaragod:['Kasaragod','Kanhangad','Nileshwar','Uppala'],
  Kollam:['Kollam','Punalur','Karunagappally','Kottarakkara','Paravur'],
  Kottayam:['Kottayam','Changanassery','Pala','Vaikom','Ettumanoor'],
  Kozhikode:['Kozhikode','Vadakara','Koyilandy','Feroke','Ramanattukara'],
  Malappuram:['Malappuram','Manjeri','Tirur','Perinthalmanna','Ponnani','Kottakkal'],
  Palakkad:['Palakkad','Ottapalam','Shoranur','Chittur','Mannarkkad'],
  Pathanamthitta:['Pathanamthitta','Thiruvalla','Adoor','Pandalam','Ranni'],
  Thiruvananthapuram:['Thiruvananthapuram','Neyyattinkara','Attingal','Varkala','Nedumangad'],
  Thrissur:['Thrissur','Chalakudy','Guruvayur','Kodungallur','Irinjalakuda','Kunnamkulam'],
  Wayanad:['Kalpetta','Mananthavady','Sulthan Bathery','Meppadi']
};
function locationOptions(district=''){return (keralaPlaces[district]||[]).map(place=>`<option value="${escapeHtml(place)}">${escapeHtml(place)}</option>`).join('')}
function openLocation(){
  const districts=Object.keys(keralaPlaces),parts=locationQuery.split(',').map(part=>part.trim()).filter(Boolean),known=parts[1]||'',initial=districts.includes(known)?known:(districts.includes(parts[0])?parts[0]:'');
  const currentTown=known===initial&&initial&&keralaPlaces[initial].some(place=>normalizeArea(place)===normalizeArea(parts[0]))?parts[0]:'';
  openModal(`<span class="eyebrow">NEAR YOU · KERALA</span><h2>Set your location</h2><p>Choose a Kerala district and town, or type a city or area to find nearby listings.</p><label class="field-label" for="districtSelect">District</label><select id="districtSelect"><option value="">Choose a district</option>${districts.map(d=>`<option value="${d}" ${d===initial?'selected':''}>${d}</option>`).join('')}</select><label class="field-label" for="placeSelect">Town or place</label><select id="placeSelect" ${initial?'':'disabled'}><option value="">Choose a town or place</option>${locationOptions(initial)}</select><label class="field-label" for="locationInput">Or type any city / area</label><input id="locationInput" placeholder="e.g. Kochi or Kakkanad" value="${escapeHtml(initial?(currentTown||''):locationQuery)}"><div class="modal-actions"><button id="setLocation" class="auth-button primary">Show nearby finds</button><button id="clearLocation" class="auth-button">Clear</button></div>`);
  const district=$('#districtSelect'),place=$('#placeSelect'),input=$('#locationInput');
  if(currentTown)place.value=currentTown;
  district.onchange=()=>{place.innerHTML=`<option value="">Choose a town or place</option>${locationOptions(district.value)}`;place.disabled=!district.value;place.value='';input.value=''};
  place.onchange=()=>{if(place.value)input.value=place.value};
  $('#setLocation').onclick=()=>{const typed=input.value.trim(),selected=!!place.value&&typed===place.value,value=selected?`${place.value}, ${district.value}`:typed?(district.value?`${typed}, ${district.value}`:typed):district.value;if(!value){toast('Choose a Kerala district and place, or type a city / area.');return}const label=selected?`${place.value}, ${district.value}`:typed?(district.value?`${typed}, ${district.value}`:typed):`${district.value}, Kerala`;applyLocation(value,label)};
  $('#clearLocation').onclick=()=>{locationQuery='';updateLocationLabel('Kerala');closeModal();renderListings();toast('Location filter cleared.')};input.addEventListener('keydown',e=>{if(e.key==='Enter')$('#setLocation').click()});
}
function welcomeModal({required=false}={}){
 const googleIcon='<svg viewBox="0 0 48 48" role="img" aria-label="Google"><path fill="#4285F4" d="M43.6 24.5c0-1.4-.1-2.7-.4-4H24v7.6h11a9.4 9.4 0 0 1-4.1 6.2v5h6.7c3.9-3.6 6-8.8 6-14.8Z"/><path fill="#34A853" d="M24 44c5.5 0 10.1-1.8 13.5-4.8l-7-5c-1.8 1.2-4.1 1.9-6.8 1.9-5.2 0-9.6-3.5-11.2-8.2H5.9v5.2A20 20 0 0 0 24 44Z"/><path fill="#FBBC05" d="M12.8 27.9a12 12 0 0 1 0-7.7V15H5.9a20 20 0 0 0 0 17.9l6.9-5Z"/><path fill="#EA4335" d="M24 12c3 0 5.7 1 7.8 3.1l5.8-5.8C34.1 6 29.5 4 24 4A20 20 0 0 0 5.9 15l6.9 5C14.4 15.5 18.8 12 24 12Z"/></svg>';
 const brand='<span class="redo-wordmark" aria-label="redo"><span>red</span><span class="redo-o-letter">o<svg class="redo-wordmark-o" viewBox="0 0 36 36" aria-hidden="true"><path d="M27.5 12.2A12 12 0 0 0 7.7 10l-2 2.3M5.7 12.3l.2-6 5.8.8M8.5 23.8A12 12 0 0 0 28.3 26l2-2.3m0 0-.2 6-5.8-.8" fill="none" stroke="currentColor" stroke-width="3.1" stroke-linecap="round" stroke-linejoin="round"/></svg></span></span>';
 const bag='<svg viewBox="0 0 180 180" role="img" aria-label="redo reusable shopping bag"><defs><linearGradient id="redoBag" x1="36" y1="62" x2="139" y2="159" gradientUnits="userSpaceOnUse"><stop stop-color="#fff"/><stop offset="1" stop-color="#eee9fb"/></linearGradient></defs><path d="M48 65 38 150q-1 11 11 11h82q11 0 10-11l-10-85Z" fill="#302276" opacity=".22"/><path d="M53 67V48c0-20 13-32 31-32s31 12 31 32v19" fill="none" stroke="#3038cb" stroke-width="10" stroke-linecap="round"/><path d="M46 62h89l10 91q1 10-10 10H46q-11 0-10-10Z" fill="url(#redoBag)" stroke="#fff" stroke-width="3"/><path d="M71 108a22 22 0 0 1 34-14m0 0-1-10m1 10-10 1M110 115a22 22 0 0 1-34 14m0 0 1 10m-1-10 10-1" fill="none" stroke="#ff685f" stroke-width="7" stroke-linecap="round" stroke-linejoin="round"/><path d="m130 48 7-12m4 25 13-6m-19-8 11 1" stroke="#ff685f" stroke-width="5" stroke-linecap="round"/></svg>';
 const html=`<section class="welcome-auth"><section class="welcome-auth-panel"><div class="login-glass-card"><div class="login-brand-lockup">${brand}<span class="login-bag-art">${bag}</span></div><div class="login-actions"><button class="welcome-google-button" id="googleLogin">${googleIcon}<span>Continue with Google</span></button><button class="welcome-guest-button" id="guestBrowse">Continue as guest</button></div></div></section></section>`;
 openModal(html);$('.modal').classList.add('welcome-auth-modal');$('#closeModal').hidden=true;
 $('#googleLogin').onclick=async()=>{if(!sbClient){authSetup();return}const {error}=await sbClient.auth.signInWithOAuth({provider:'google',options:{redirectTo:`${location.origin}${location.pathname}`,queryParams:{prompt:'select_account'}}});if(error)toast(error.message)};
 $('#guestBrowse').onclick=()=>{sessionStorage.setItem('redo_guest_session','1');closeModal();toast('Browsing as guest. Sign in any time to post or contact sellers.')};
}
function loginModal(){welcomeModal()}
function updateLogin(){const button=$('#loginBtn');if(!user){button.textContent='Login';button.onclick=loginModal;return}button.textContent='My account';button.onclick=()=>openSettings('profile')}
function renderSettingsTab(tab,profile){
 const email=user?.email||'Not available',tabs=[['profile','Profile','◉'],['preferences','Preferences','☼'],['privacy','Privacy & safety','◇']];let content='';
 if(tab==='profile'){
  const joined=user?.created_at?new Date(user.created_at).toLocaleDateString(undefined,{year:'numeric',month:'long'}):'—';
  content=`<div class="settings-section-heading"><div><span class="eyebrow">YOUR REDO ACCOUNT</span><h3>Profile details</h3><p>Update the information connected to your account.</p></div><span class="settings-status">CONNECTED</span></div><form id="profileSettingsForm" class="settings-form"><div class="settings-form-grid"><label class="settings-field settings-field-wide"><span>Display name</span><input name="display_name" required minlength="2" maxlength="60" value="${escapeHtml(profile.display_name||'')}" placeholder="How people see you"></label><label class="settings-field"><span>Email address</span><input value="${escapeHtml(email)}" readonly><small>Managed by your sign-in provider.</small></label><label class="settings-field"><span>Member since</span><input value="${escapeHtml(joined)}" readonly></label><label class="settings-field settings-field-wide"><span>Phone number for agreed deals</span><input name="phone_number" type="tel" inputmode="tel" autocomplete="tel" maxlength="24" value="${escapeHtml(profile.phone_number||'')}" placeholder="e.g. +91 98765 43210"><small>Private to you unless both sides press Deal OK in the same chat.</small></label><label class="settings-field"><span>City (private)</span><input name="city" maxlength="80" value="${escapeHtml(profile.city||'')}" placeholder="e.g. Kochi"></label><label class="settings-field settings-field-wide"><span>About you (private)</span><textarea name="bio" rows="3" maxlength="240" placeholder="A short introduction">${escapeHtml(profile.bio||'')}</textarea></label><label class="settings-field settings-field-wide"><span>Profile photo URL (optional)</span><input name="avatar_url" type="url" value="${escapeHtml(profile.avatar_url||'')}" placeholder="https://…"><small>Use a secure https image link. Your name and photo may appear with your listings.</small></label></div><div class="settings-form-footer"><span id="profileSaveStatus" class="settings-inline-status" aria-live="polite">Your phone number stays private until both people agree.</span><button class="auth-button primary settings-save" id="saveProfileButton">Save profile</button></div></form>`;
 }else if(tab==='preferences'){
  const lang=readLocal('language')||'en',theme=document.documentElement.dataset.theme||'light';
  content=`<div class="settings-section-heading"><div><span class="eyebrow">MAKE REDO YOURS</span><h3>Preferences</h3><p>These choices stay saved on this device.</p></div></div><div class="settings-option"><div><b>Language</b><span>Choose the language used across the marketplace.</span></div><select id="settingsLanguage"><option value="en" ${lang==='en'?'selected':''}>English</option><option value="ml" ${lang==='ml'?'selected':''}>മലയാളം</option></select></div><div class="settings-option"><div><b>Appearance</b><span>Choose a comfortable color theme.</span></div><button class="settings-choice" id="settingsTheme">${theme==='dark'?'☾ Dark mode':'☀ Light mode'} · Change</button></div><div class="settings-option"><div><b>Browse location</b><span>${escapeHtml($('.location-select span:nth-child(2)')?.textContent||'Kerala')} · choose a district or town.</span></div><button class="settings-choice" id="settingsLocation">Change location</button></div><p class="settings-note">Your language and appearance are stored in this browser. Location is used to filter listings and is not shared with sellers.</p>`;
 }else{
  const localCount=localSavedFavorites().length;
  content=`<div class="settings-section-heading"><div><span class="eyebrow">YOUR CONTROL</span><h3>Privacy &amp; safety</h3><p>Review what your account shares and manage this device’s saved finds.</p></div></div><div class="settings-privacy-card"><span class="settings-privacy-icon">◎</span><div><b>Account information</b><p>Your email stays with your sign-in account. Your display name and profile photo may appear with your listings. Your city and introduction remain private to your account.</p></div></div><div class="settings-option"><div><b>Saved finds on this device</b><span>${localCount} locally saved ${localCount===1?'find':'finds'}; synced account favorites are kept separately.</span></div><button class="settings-choice danger" id="clearLocalFavorites" ${localCount?'':'disabled'}>Clear device saves</button></div><div class="settings-privacy-card"><span class="settings-privacy-icon">✳</span><div><b>Meet safely</b><p>Meet in public, inspect items before paying, and never share one-time codes or banking passwords.</p><button class="settings-text-button" id="settingsSafetyTips">Read all safety tips ↗</button></div></div>`;
 }
 const initials=String(profile.display_name||email||'R').trim().slice(0,1).toUpperCase();
 openModal(`<div class="settings-shell"><header class="settings-header"><div><span class="eyebrow">ACCOUNT CENTRE</span><h2>Settings</h2><p>Manage your redo profile, preferences and privacy.</p></div><div class="settings-account-chip"><span>${escapeHtml(initials)}</span><div><b>${escapeHtml(profile.display_name||'redo member')}</b><small>${escapeHtml(email)}</small></div></div></header><div class="settings-layout"><nav class="settings-nav" aria-label="Settings sections">${tabs.map(([id,label,icon])=>`<button type="button" data-settings-tab="${id}" class="${tab===id?'active':''}" aria-current="${tab===id?'page':'false'}"><span>${icon}</span>${label}<b>›</b></button>`).join('')}</nav><section class="settings-panel" id="settingsPanel">${content}</section></div><footer class="settings-footer"><span>Signed in · ${escapeHtml(user?.app_metadata?.provider||'account')}</span><div><button type="button" id="settingsListings">My listings</button><button type="button" id="settingsSaved">Saved searches</button><button type="button" id="settingsSignOut">Sign out</button></div></footer></div>`);
 $('.modal').classList.add('settings-modal');$$('[data-settings-tab]').forEach(button=>button.onclick=()=>renderSettingsTab(button.dataset.settingsTab,profile));$('#settingsListings').onclick=myListingsModal;$('#settingsSaved').onclick=savedSearchesModal;$('#settingsSignOut').onclick=signOutRedo;
 if(tab==='profile')$('#profileSettingsForm').onsubmit=async event=>{event.preventDefault();const button=$('#saveProfileButton'),status=$('#profileSaveStatus'),form=new FormData(event.currentTarget),displayName=String(form.get('display_name')).trim(),phoneNumber=String(form.get('phone_number')||'').trim(),bio=String(form.get('bio')||'').trim(),city=String(form.get('city')||'').trim(),avatarUrl=String(form.get('avatar_url')||'').trim();if(phoneNumber&&!/^\+?[0-9 ()-]{7,24}$/.test(phoneNumber)){status.textContent='Enter a valid phone number, including your country code.';return}if(avatarUrl){try{if(new URL(avatarUrl).protocol!=='https:')throw new Error()}catch{status.textContent='Profile photo link must be a valid https URL.';return}}button.disabled=true;button.textContent='Saving…';status.textContent='Saving your profile and private contact details…';const {error:profileError}=await sbClient.from('profiles').upsert({user_id:user.id,display_name:displayName,avatar_url:avatarUrl||null},{onConflict:'user_id'});if(profileError){status.textContent=`Could not save your public profile: ${profileError.message}`;button.disabled=false;button.textContent='Save profile';return}const contactResult=phoneNumber?await sbClient.from('private_contact_details').upsert({user_id:user.id,full_name:displayName,phone_number:phoneNumber,updated_at:new Date().toISOString()},{onConflict:'user_id'}):await sbClient.from('private_contact_details').delete().eq('user_id',user.id);if(contactResult.error){status.textContent=`Profile saved, but private phone save failed: ${contactResult.error.message}. Run the updated schema.sql in Supabase.`;button.disabled=false;button.textContent='Save profile';return}user={...user,user_metadata:{...user.user_metadata,full_name:displayName,name:displayName,bio,city,avatar_url:avatarUrl||null}};status.textContent='Your profile and private contact details are saved.';toast('Profile saved.');button.disabled=false;button.textContent='Save profile';renderSettingsTab('profile',{display_name:displayName,avatar_url:avatarUrl,bio,city,phone_number:phoneNumber})};
 if(tab==='preferences'){if($('#settingsLanguage'))$('#settingsLanguage').onchange=event=>{writeLocal('language',event.target.value);applyLanguage(event.target.value);renderSettingsTab('preferences',profile)};$('#settingsTheme').onclick=()=>{$('#themeToggle').click();renderSettingsTab('preferences',profile)};$('#settingsLocation').onclick=()=>{closeModal();openLocation()}}
 if(tab==='privacy'){if($('#clearLocalFavorites'))$('#clearLocalFavorites').onclick=()=>{if(!confirm('Clear only saved finds stored on this device? Synced account favorites will remain.'))return;localStorage.removeItem('redo_favorites');localStorage.removeItem('olxFavorites');favorites=isRealUser()?favorites:new Set();renderListings();renderSettingsTab('privacy',profile);toast('Device-only saved finds cleared.')};$('#settingsSafetyTips').onclick=()=>showInfo('Safety tips','Meet in a public place, inspect an item before paying, keep conversation on redo, and never share one-time codes or banking passwords. Report suspicious listings from the listing details.')}
}
async function openSettings(tab='profile'){if(!isRealUser()||!sbClient){loginModal();toast('Sign in to manage your account settings.');return}const metadata=user.user_metadata||{};let stored={};const {data,error}=await sbClient.from('profiles').select('display_name,avatar_url').eq('user_id',user.id).maybeSingle();if(error)toast(`Could not refresh public profile: ${error.message}`);if(data)stored=data;let contact={};const privateResult=await sbClient.from('private_contact_details').select('full_name,phone_number').eq('user_id',user.id).maybeSingle();if(!privateResult.error&&privateResult.data)contact=privateResult.data;const profile={display_name:stored.display_name||metadata.full_name||metadata.name||user.email?.split('@')[0]||'redo member',avatar_url:stored.avatar_url||metadata.avatar_url||'',bio:metadata.bio||'',city:metadata.city||'',phone_number:contact.phone_number||''};renderSettingsTab(tab,profile)}
async function signOutRedo(){if(isRealUser()&&sbClient){const {error}=await sbClient.auth.signOut();if(error){toast(`Could not sign out: ${error.message}`);return}}user=null;favorites=new Set(localSavedFavorites());updateLogin();renderListings();closeModal();toast('You’re signed out.')}
async function myListingsModal(){let own;if(isRealUser()){const {data,error}=await sbClient.from('listings').select('*').eq('user_id',user.id).order('created_at',{ascending:false});if(error){toast(`Could not load your listings: ${error.message}`);return}own=(data||[]).map(mapListing)}else own=localListings().map(x=>({...x,img:x.img||x.photo_url}));const rows=own.map(item=>`<div class="my-listing"><div><b>${escapeHtml(item.title)}</b><span>${money(item.price)} · ${escapeHtml(item.area)} · ${escapeHtml(item.status||'active')}</span></div><div class="my-listing-actions"><button data-edit-listing="${escapeHtml(item.id)}">Edit</button><button data-sold="${escapeHtml(item.id)}" ${item.status==='sold'?'disabled':''}>Mark sold</button><button data-delete-listing="${escapeHtml(item.id)}">Delete</button></div></div>`).join('');openModal(`<span class="eyebrow">SELLER DASHBOARD</span><h2>My listings</h2>${rows||'<p>You have not posted any listings yet.</p>'}<button class="auth-button primary" id="createListingFromDashboard">Post a new ad</button>`);$('#createListingFromDashboard').onclick=sellModal;$$('[data-edit-listing]').forEach(button=>button.onclick=()=>editListing(own.find(item=>item.id===button.dataset.editListing)));$$('[data-sold]').forEach(button=>button.onclick=async()=>{const id=button.dataset.sold;if(isRealUser()){const {error}=await sbClient.from('listings').update({status:'sold'}).eq('id',id).eq('user_id',user.id);if(error){toast(error.message);return}}else{const saved=localListings().map(item=>item.id===id?{...item,status:'sold'}:item);writeLocal('listings',JSON.stringify(saved))}listings=listings.filter(item=>item.id!==id);renderListings();await myListingsModal();toast('Listing marked sold.')});$$('[data-delete-listing]').forEach(button=>button.onclick=async()=>{if(!confirm('Delete this listing? This cannot be undone.'))return;const id=button.dataset.deleteListing;if(isRealUser()){const {error}=await sbClient.from('listings').delete().eq('id',id).eq('user_id',user.id);if(error){toast(error.message);return}}else writeLocal('listings',JSON.stringify(localListings().filter(item=>item.id!==id)));listings=listings.filter(item=>item.id!==id);await myListingsModal();renderListings();toast('Listing deleted.')})}
function editListing(item){openModal(`<span class="eyebrow">EDIT YOUR AD</span><h2>Update listing</h2><form id="editListingForm"><label class="field-label">Title</label><input name="title" required maxlength="70" value="${escapeHtml(item.title)}"><div class="form-row"><div><label class="field-label">Category</label><select name="category">${categories.map(([name])=>`<option ${name===item.category?'selected':''}>${name}</option>`).join('')}</select></div><div><label class="field-label">Price (₹)</label><input name="price" type="number" min="0" required value="${Number(item.price)||0}"></div></div><label class="field-label">Description</label><textarea name="description" rows="3" required maxlength="2000">${escapeHtml(item.description||item.desc)}</textarea><label class="field-label">Area</label><input name="area" required maxlength="100" value="${escapeHtml(item.area)}"><button class="auth-button primary">Save changes</button></form>`);$('#editListingForm').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.target),changes={title:String(form.get('title')).trim(),category:String(form.get('category')),price:Number(form.get('price')),description:String(form.get('description')).trim(),area:String(form.get('area')).trim()};if(isRealUser()){const {error}=await sbClient.from('listings').update(changes).eq('id',item.id).eq('user_id',user.id);if(error){toast(error.message);return}}else{const saved=localListings().map(listing=>listing.id===item.id?{...listing,...changes,desc:changes.description}:listing);writeLocal('listings',JSON.stringify(saved))}listings=listings.map(listing=>listing.id===item.id?{...listing,...changes,desc:changes.description}:listing);closeModal();renderListings();toast('Listing updated.')}}
function localSavedFavorites(){return localArray('favorites')}
async function loadFavorites(){if(!isRealUser()||!sbClient)return;const {data,error}=await sbClient.from('favorites').select('listing_id').eq('user_id',user.id);if(error){toast(`Could not load saved listings: ${error.message}`);return}favorites=new Set([...localSavedFavorites(),...data.map(row=>row.listing_id)]);renderListings()}
function mapListing(row){return{id:row.id,user_id:row.user_id,category:row.category,price:Number(row.price),title:row.title,area:row.area,description:row.description,photo_url:row.photo_url,time:new Date(row.created_at).toLocaleDateString(),created_at:row.created_at}}
async function loadListings(){if(!sbClient){listingsLoading=false;return}const {data,error}=await sbClient.from('listings').select('id,user_id,category,price,title,area,description,photo_url,created_at,status').eq('status','active').order('created_at',{ascending:false}).limit(100);listingsLoading=false;if(error){renderListings();toast(`Could not load marketplace data: ${error.message}`);return}listings=(data||[]).map(mapListing);renderListings()}
async function syncUser(nextUser){user=nextUser||null;updateLogin();if(!isRealUser()){favorites=new Set(localSavedFavorites());await loadListings();return}const displayName=user.user_metadata?.full_name||user.user_metadata?.name||user.phone||user.email||'redo member';await sbClient.from('profiles').upsert({user_id:user.id,display_name:displayName,avatar_url:user.user_metadata?.avatar_url||null},{onConflict:'user_id'});await Promise.all([loadListings(),loadFavorites()])}
function authSetupInfo(){if(!sbClient)authSetup()}
async function uploadListingPhoto(file,listingId){if(!file)return null;if(!/^image\/(jpeg|png|webp)$/.test(file.type))throw new Error('Choose a JPG, PNG or WebP image.');if(file.size>8*1024*1024)throw new Error('Choose an image smaller than 8 MB.');const path=`${user.id}/${listingId}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const {error}=await sbClient.storage.from('listing-images').upload(path,file,{contentType:file.type,upsert:false});if(error)throw error;return sbClient.storage.from('listing-images').getPublicUrl(path).data.publicUrl}
function fileAsDataUrl(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read that image.'));reader.readAsDataURL(file)})}
function sellModal(){if(!user){loginModal();toast('Sign in to post a listing. Guests can browse and save finds on this device.');return}openModal(`<span class="eyebrow">SELL SOMETHING</span><h2>Post your ad</h2><p>Tell your neighborhood about the good thing you’re letting go.</p><form id="listingForm"><label class="field-label">Listing title</label><input name="title" required maxlength="70" placeholder="What are you selling?"><div class="form-row"><div><label class="field-label">Category</label><select name="category">${categories.map(c=>`<option>${c[0]}</option>`).join('')}</select></div><div><label class="field-label">Price (₹)</label><input name="price" type="number" min="0" required placeholder="0"></div></div><label class="field-label">Description</label><textarea name="description" rows="3" required maxlength="500" placeholder="Condition, details, and what makes it a good find"></textarea><label class="field-label">Your area</label><input name="area" required maxlength="100" placeholder="Neighborhood, city"><label class="field-label">Photo (optional)</label><input name="photo" type="file" accept="image/jpeg,image/png,image/webp"><label class="field-label">Or paste a photo URL</label><input name="photo_url" type="url" placeholder="https://..."><button class="auth-button primary" style="margin-top:15px">Publish listing</button></form>`);
  $('#listingForm').onsubmit=async e=>{e.preventDefault();const submit=e.submitter;submit.disabled=true;submit.textContent='Publishing…';try{const form=new FormData(e.target),id=crypto.randomUUID(),photo=form.get('photo'),photoUrlInput=String(form.get('photo_url')||'').trim();let photoUrl=photoUrlInput||null;if(photo&&photo.size){if(isRealUser())photoUrl=await uploadListingPhoto(photo,id);else{if(photo.size>700000)throw new Error('Choose an image under 700 KB when browsing without a connected account.');photoUrl=await fileAsDataUrl(photo)}}const draft={title:String(form.get('title')).trim(),category:String(form.get('category')),price:Number(form.get('price')),description:String(form.get('description')).trim(),area:String(form.get('area')).trim(),photo_url:photoUrl||seedListings[2].photo_url};if(isRealUser()){const {data,error}=await sbClient.from('listings').insert({...draft,id,user_id:user.id,status:'active'}).select().single();if(error)throw error;listings.unshift(mapListing(data))}else{const created={...draft,id:'u'+Date.now(),img:draft.photo_url,desc:draft.description,time:'Just now'};const saved=localListings();saved.unshift(created);writeLocal('listings',JSON.stringify(saved));listings.unshift(created)}closeModal();favoritesOnly=false;activeCategory='all';query='';priceLimit=0;renderListings();$('#latest').scrollIntoView({behavior:'smooth'});toast('Your listing is live.')}catch(error){toast(error.message||'Could not publish this listing.');submit.disabled=false;submit.textContent='Publish listing'}};
}
async function toggleFavorite(id){const isSaved=favorites.has(id),listing=listings.find(item=>item.id===id);if(isRealUser()&&sbClient&&listing?.user_id){if(isSaved){const {error}=await sbClient.from('favorites').delete().eq('user_id',user.id).eq('listing_id',id);if(error){toast(error.message);return}favorites.delete(id)}else{const {error}=await sbClient.from('favorites').insert({user_id:user.id,listing_id:id});if(error){toast(error.message);return}favorites.add(id)}}else{if(isSaved)favorites.delete(id);else favorites.add(id);writeLocal('favorites',JSON.stringify([...favorites]))}renderListings();const button=$('#modalFav');if(button&&listing)button.textContent=favorites.has(id)?'♥':'♡';toast(favorites.has(id)?'Added to your saved finds.':'Removed from saved finds.')}
function listingModal(id){
  const item=listings.find(listing=>listing.id===id);if(!item)return;
  const related=listings.filter(listing=>listing.id!==item.id&&listing.category===item.category).slice(0,2);
  const posted=item.created_at?new Date(item.created_at).toLocaleDateString():item.time||'Recently';
  const description=item.description||item.desc||'Contact the seller to learn more about this listing.';
  openModal(`<div class="listing-detail-grid">
    <div class="listing-gallery"><img src="${escapeHtml(safeImage(item.photo_url||item.img))}" alt="${escapeHtml(item.title)}"><div class="gallery-caption"><span>LOCAL FIND</span><span>${escapeHtml(item.category)}</span></div></div>
    <div class="listing-detail-panel"><span class="eyebrow">${escapeHtml(item.category.toUpperCase())} · ${escapeHtml(item.area.toUpperCase())}</span>
      <div class="listing-price">${money(item.price)}</div><h2 class="listing-title">${escapeHtml(item.title)}</h2>
      <p class="listing-desc">${escapeHtml(description)}</p>
      <div class="listing-facts"><div><span>LOCATION</span><b>${escapeHtml(item.area)}</b></div><div><span>POSTED</span><b>${escapeHtml(posted)}</b></div><div><span>SELLER</span><b>${item.user_id?'Marketplace member':'Community listing'}</b></div></div>
      <div class="safety-note"><b>Meet safely</b><span>Keep messages on the marketplace. Meet in a public place and inspect the item before paying.</span></div>
      <div class="modal-actions"><button class="modal-contact" id="contactSeller">Chat with seller</button><button class="modal-fav" id="modalFav">${favorites.has(item.id)?'♥':'♡'} Save</button><button class="modal-action" id="shareListing">Share</button><button class="modal-action danger" id="reportListing">Report</button></div>
      ${related.length?`<div class="related-listings"><div class="related-heading"><b>More in ${escapeHtml(item.category)}</b><button id="browseCategory">See all</button></div>${related.map(other=>`<button class="related-item" data-related-id="${escapeHtml(other.id)}"><img src="${escapeHtml(safeImage(other.photo_url||other.img))}" alt=""><span><b>${escapeHtml(other.title)}</b><small>${money(other.price)} · ${escapeHtml(other.area)}</small></span></button>`).join('')}</div>`:''}
    </div></div>`,true);
  $('#contactSeller').onclick=()=>openChat(item,null,{type:'listing',listingId:item.id});$('#modalFav').onclick=()=>toggleFavorite(item.id);$('#shareListing').onclick=()=>shareListing(item);$('#reportListing').onclick=()=>listingReportModal(item);
  $$('[data-related-id]').forEach(button=>button.onclick=()=>listingModal(button.dataset.relatedId));
  if($('#browseCategory'))$('#browseCategory').onclick=()=>{activeCategory=item.category;favoritesOnly=false;renderListings();closeModal();$('#latest').scrollIntoView({behavior:'smooth'});toast(`Showing ${item.category} listings.`)};
}
async function fetchConversation(listing,existing){if(existing)return existing;if(!isRealUser()||!listing.user_id) return null;if(listing.user_id===user.id){showInfo('Your listing','You cannot start a chat with yourself.');return null}const key={listing_id:listing.id,buyer_id:user.id,seller_id:listing.user_id};const {data,error}=await sbClient.from('conversations').select('*').match(key).maybeSingle();if(error)throw error;if(data)return data;const created=await sbClient.from('conversations').insert(key).select().single();if(created.error){const retry=await sbClient.from('conversations').select('*').match(key).maybeSingle();if(retry.data)return retry.data;throw created.error}return created.data}

function renderDealPanel(role,state={}){
 const accepted=role==='BUYING'?state.buyer_confirmed:state.seller_confirmed,complete=state.buyer_confirmed&&state.seller_confirmed,contacts=state.contacts;
 if(complete&&contacts)return `<section class="deal-panel deal-complete"><div class="deal-panel-copy"><span class="deal-status-dot"></span><div><b>Deal confirmed by both people</b><p>Contact details are now shared privately in this conversation.</p></div></div><div class="deal-contact-grid">${['buyer','seller'].map(key=>{const contact=contacts[key]||{};return `<article class="deal-contact"><small>${key==='buyer'?'BUYER':'SELLER'}</small><b>${escapeHtml(contact.full_name||'redo member')}</b><a href="tel:${escapeHtml(contact.phone_number||'')}">${escapeHtml(contact.phone_number||'No phone provided')}</a></article>`}).join('')}</div></section>`;
 return `<section class="deal-panel"><div class="deal-panel-copy"><span class="deal-status-dot"></span><div><b>${accepted?'You confirmed — waiting for the other person':'Ready to make a deal?'}</b><p>${state[role==='BUYING'?'seller_confirmed':'buyer_confirmed']?'The other person agreed. Confirm too to exchange names and phone numbers.':'Both people need to confirm before private contact details are shared.'}</p></div></div><button class="deal-ok-button" id="dealOk" ${accepted?'disabled':''}>${accepted?'✓ Deal OK':'Deal OK'}</button></section>`;
}
async function getDealState(conversationId){const {data,error}=await sbClient.rpc('get_conversation_deal_state',{p_conversation_id:conversationId});if(error)throw error;return data||{buyer_confirmed:false,seller_confirmed:false,contacts:null}}
async function confirmDeal(conversationId){const {data,error}=await sbClient.rpc('confirm_conversation_deal',{p_conversation_id:conversationId});if(error)throw error;return data}

async function openChat(listing,conversation=null,returnTarget=null,fromHistory=false){
  if(!user){loginModal();toast('Sign in to message sellers. You can continue browsing as a guest.');return}
  if(isRealUser()&&!listing.user_id){showInfo('Demo listing','This sample listing has no live seller account. Live chat works on listings posted to your connected marketplace.');return}
  let thread=conversation;let threadMessages=[];
  if(isRealUser()){
    try{thread=await fetchConversation(listing,conversation);if(!thread)return;const {data,error}=await sbClient.from('messages').select('id,sender_id,body,created_at').eq('conversation_id',thread.id).order('created_at',{ascending:true});if(error)throw error;threadMessages=data||[]}
    catch(error){toast('Could not open chat: '+error.message);return}
  }else threadMessages=localMessages.filter(m=>m.listingId===listing.id);
  if(!chatBackPushed){chatReturnTarget=returnTarget||chatReturnTarget||{type:'listing',listingId:listing.id};history.pushState({...history.state,redoChat:true},'',location.href);chatBackPushed=true}
  else if(returnTarget)chatReturnTarget=returnTarget;
  chatContext={listing,thread};
  const role=!thread||thread.buyer_id===user.id?'BUYING':'SELLING';
  const peer=role==='BUYING'?'Seller':'Buyer';
  const backLabel=chatReturnTarget?.type==='inbox'?'Back to messages':'Back to listing';
  const bubbles=threadMessages.map(m=>{const mine=!isRealUser()||m.sender_id===user.id;const time=m.created_at?new Date(m.created_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):(m.time||'');return '<div class="chat-message '+(mine?'outgoing':'incoming')+'"><div class="chat-bubble"><p>'+escapeHtml(m.body||m.text)+'</p><small>'+escapeHtml(time)+' &middot; '+(mine?'You':peer)+'</small></div></div>'}).join('');
  let dealState={buyer_confirmed:false,seller_confirmed:false,contacts:null};
  if(isRealUser()){try{dealState=await getDealState(thread.id)}catch(error){console.warn('Deal confirmation schema is not ready:',error.message)}}
  const html='<section class="chat-shell"><header class="chat-header"><button type="button" class="chat-back" id="chatBack" aria-label="'+backLabel+'"><span aria-hidden="true">&larr;</span><small>Back</small></button><div class="chat-peer"><span class="chat-avatar">'+peer.charAt(0)+'</span><div><strong>'+peer+'</strong><small>'+escapeHtml(listing.area)+' &middot; on redo</small></div></div><span class="chat-protected">PRIVATE CHAT</span></header><div class="chat-listing-preview"><img src="'+escapeHtml(safeImage(listing.photo_url||listing.img))+'" alt=""><div><small>ABOUT THIS LISTING</small><b>'+escapeHtml(listing.title)+'</b><strong>'+money(listing.price)+'</strong></div><span class="chat-role-pill">'+role+'</span></div>'+ (isRealUser()?renderDealPanel(role,dealState):'')+'<div class="chat-history" aria-live="polite">'+(bubbles||'<div class="chat-welcome"><span>&#10033;</span><b>Start a good conversation</b><p>Ask about the condition, availability, or a safe time to meet.</p></div>')+'</div><form id="chatForm" class="chat-composer"><label class="sr-only" for="chatMessage">Your message</label><textarea id="chatMessage" name="message" rows="2" required maxlength="500" placeholder="Write a message..."></textarea><button class="chat-send" aria-label="Send message"><span>Send</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m4 12 16-8-5.5 16-3-6.5L4 12Z"/><path d="M11.5 13.5 20 4"/></svg></button></form><p class="chat-safety"><span>◆</span> Keep payments and personal codes out of chat. Meet safely in public.</p></section>';
  openModal(html);$('.modal').classList.add('chat-modal');$('#closeModal').onclick=handleChatBack;$('#chatBack').onclick=handleChatBack;
  if(isRealUser()){currentConversationId=thread.id;activeChannel=sbClient.channel('messages:'+thread.id).on('postgres_changes',{event:'INSERT',schema:'public',table:'messages',filter:'conversation_id=eq.'+thread.id},payload=>{if(payload.new.sender_id===user?.id||currentConversationId!==thread.id)return;const box=$('.chat-history');if(box){const time=new Date(payload.new.created_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});box.insertAdjacentHTML('beforeend','<div class="chat-message incoming"><div class="chat-bubble"><p>'+escapeHtml(payload.new.body)+'</p><small>'+escapeHtml(time)+' &middot; '+peer+'</small></div></div>');box.scrollTop=box.scrollHeight}}).on('postgres_changes',{event:'*',schema:'public',table:'conversation_deal_confirmations',filter:'conversation_id=eq.'+thread.id},async()=>{if(currentConversationId!==thread.id)return;try{dealState=await getDealState(thread.id);const panel=$('.deal-panel');if(panel){panel.outerHTML=renderDealPanel(role,dealState);bindDealButton()}}catch(error){console.warn('Could not refresh deal confirmation:',error.message)}}).subscribe()}
  const box=$('.chat-history');if(box)box.scrollTop=box.scrollHeight;
  const bindDealButton=()=>{const button=$('#dealOk');if(!button)return;button.onclick=async()=>{button.disabled=true;button.textContent='Confirming…';try{dealState=await confirmDeal(thread.id);const panel=$('.deal-panel');if(panel)panel.outerHTML=renderDealPanel(role,dealState);toast(dealState.contacts?'Both agreed. Contact details exchanged.':'Your agreement is saved. Waiting for the other person.');if(dealState.contacts)document.querySelector('.deal-panel')?.scrollIntoView({behavior:'smooth',block:'nearest'});bindDealButton()}catch(error){button.disabled=false;button.textContent='Deal OK';toast(error.message.includes('private_contact_details')||error.message.includes('schema')?'Save your name and phone under Settings first, and make sure the updated Supabase schema.sql has been run.':`Could not confirm the deal: ${error.message}`)}}};bindDealButton();
  $('#chatForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,send=e.submitter,text=new FormData(form).get('message').trim();if(!text)return;send.disabled=true;try{if(isRealUser()){const {error}=await sbClient.from('messages').insert({conversation_id:thread.id,sender_id:user.id,body:text});if(error)throw error;await sbClient.from('conversations').update({last_message_at:new Date().toISOString()}).eq('id',thread.id)}else{localMessages.push({listingId:listing.id,text,time:new Date().toLocaleString()});writeLocal('messages',JSON.stringify(localMessages))}await openChat(listing,thread,chatReturnTarget,true);toast('Message sent.')}catch(error){toast('Could not send message: '+error.message);send.disabled=false}};
}
async function messagesModal(role='buying'){
  role=role==='selling'?'selling':'buying';
  if(!user){openModal('<div class="inbox-shell"><span class="eyebrow">YOUR INBOX</span><h2>Sign in to see messages</h2><p>Sign in with Google to view conversations and contact sellers.</p><button class="auth-button primary" id="inboxLogin">Continue to sign in</button></div>');$('#inboxLogin').onclick=loginModal;return}
  if(!isRealUser()){openModal('<div class="inbox-shell"><span class="eyebrow">YOUR INBOX</span><h2>Connect an account to chat</h2><p>Sign in to keep buyer and seller conversations in sync.</p><button class="auth-button primary" id="inboxLogin">Continue to sign in</button></div>');$('#inboxLogin').onclick=loginModal;return}
  const column=role==='buying'?'buyer_id':'seller_id';
  const {data,error}=await sbClient.from('conversations').select('*').eq(column,user.id).order('last_message_at',{ascending:false});
  if(error){toast('Could not load inbox: '+error.message);return}
  const rows=data||[];
  const cards=rows.map(row=>{const item=listings.find(x=>x.id===row.listing_id);if(!item)return '';const other=role==='buying'?'Seller':'Buyer';const when=row.last_message_at?new Date(row.last_message_at).toLocaleDateString():'New';return '<button class="conversation-card" data-live-chat="'+escapeHtml(row.id)+'" data-listing-id="'+escapeHtml(item.id)+'"><span class="conversation-thumb"><img src="'+escapeHtml(safeImage(item.photo_url||item.img))+'" alt=""></span><span class="conversation-copy"><span class="conversation-title"><b>'+escapeHtml(item.title)+'</b><time>'+escapeHtml(when)+'</time></span><span class="conversation-meta">'+other+' &middot; '+escapeHtml(item.area)+'</span><span class="conversation-preview">'+(role==='buying'?'You asked about this find':'A buyer asked about your listing')+'</span></span><span class="conversation-arrow">&rsaquo;</span></button>'}).join('');
  const empty=role==='buying'?'Your chats with sellers will appear here. Open a listing and ask a question to get started.':'Buyer conversations about your listings will appear here.';
  openModal('<section class="inbox-shell"><div class="inbox-heading"><div><span class="eyebrow">YOUR REDO INBOX</span><h2>Messages</h2><p>Every conversation stays connected to its listing.</p></div><span class="inbox-count">'+rows.length+'</span></div><div class="inbox-tabs" role="tablist" aria-label="Conversation role"><button type="button" data-inbox-role="buying" class="'+(role==='buying'?'active':'')+'" aria-selected="'+(role==='buying')+'">Buying <span>Chats with sellers</span></button><button type="button" data-inbox-role="selling" class="'+(role==='selling'?'active':'')+'" aria-selected="'+(role==='selling')+'">Selling <span>Chats with buyers</span></button></div><div class="conversation-list">'+(cards||'<div class="inbox-empty"><span>&#10033;</span><b>No '+(role==='buying'?'buyer':'seller')+' chats yet</b><p>'+empty+'</p>'+(role==='buying'?'<button type="button" id="inboxBrowse">Explore listings</button>':'')+'</div>')+'</div></section>');
  $$('[data-inbox-role]').forEach(button=>button.onclick=()=>messagesModal(button.dataset.inboxRole));
  if($('#inboxBrowse'))$('#inboxBrowse').onclick=()=>{closeModal();$('#latest').scrollIntoView({behavior:'smooth'})};
  $$('.conversation-card').forEach(button=>button.onclick=()=>{const row=rows.find(r=>r.id===button.dataset.liveChat);const item=listings.find(x=>x.id===button.dataset.listingId);if(item&&row)openChat(item,row,{type:'inbox',role})});
}
function currentSearch(){return{query,category:activeCategory,area:locationQuery,max_price:priceLimit||null}}
async function saveCurrentSearch(){if(!user){loginModal();toast('Sign in to sync saved searches. You can still save favorites as a guest.');return}const filters=currentSearch();if(!filters.query&&filters.category==='all'&&!filters.area&&!filters.max_price){toast('Search or choose a filter first.');return}const name=[filters.query,filters.category!=='all'?filters.category:'',filters.area].filter(Boolean).join(' · ')||'Marketplace search';if(isRealUser()){const {error}=await sbClient.from('saved_searches').insert({user_id:user.id,name,...filters});if(error){toast(`Could not save search: ${error.message}`);return}}else{const saved=localArray('savedSearches');saved.unshift({id:`s${Date.now()}`,name,...filters});writeLocal('savedSearches',JSON.stringify(saved))}toast('Search saved to your account.')}
async function savedSearchesModal(){if(!user){loginModal();return}let searches;if(isRealUser()){const {data,error}=await sbClient.from('saved_searches').select('*').eq('user_id',user.id).order('created_at',{ascending:false});if(error){toast(`Could not load saved searches: ${error.message}`);return}searches=data||[]}else searches=localArray('savedSearches');openModal(`<span class="eyebrow">YOUR SHORTLIST</span><h2>Saved searches</h2>${searches.map(item=>`<div class="my-listing"><div><b>${escapeHtml(item.name)}</b><span>${escapeHtml([item.category!=='all'?item.category:'',item.area,item.max_price?`Up to ${money(item.max_price)}`:''].filter(Boolean).join(' · ')||'All listings')}</span></div><div class="my-listing-actions"><button data-run-search="${escapeHtml(item.id)}">View</button><button data-remove-search="${escapeHtml(item.id)}">Remove</button></div></div>`).join('')||'<p>No saved searches yet. Search for something and save it to find it quickly later.</p>'}`);$$('[data-run-search]').forEach(button=>button.onclick=()=>{const item=searches.find(search=>search.id===button.dataset.runSearch);if(!item)return;query=item.query||'';activeCategory=item.category||'all';locationQuery=item.area||'';priceLimit=Number(item.max_price)||0;favoritesOnly=false;$('#searchInput').value=query;updateLocationLabel(locationQuery||'India');closeModal();renderListings();$('#latest').scrollIntoView({behavior:'smooth'});toast('Saved search applied.')});$$('[data-remove-search]').forEach(button=>button.onclick=async()=>{const id=button.dataset.removeSearch;if(isRealUser()){const {error}=await sbClient.from('saved_searches').delete().eq('id',id).eq('user_id',user.id);if(error){toast(error.message);return}}else writeLocal('savedSearches',JSON.stringify(localArray('savedSearches').filter(item=>item.id!==id)));await savedSearchesModal();toast('Saved search removed.')})}
async function shareListing(item){const url=new URL(location.href);url.hash='';url.searchParams.set('listing',item.id);const share={title:item.title,text:`${item.title} · ${money(item.price)} · ${item.area}`,url:url.toString()};try{if(navigator.share)await navigator.share(share);else if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(share.url);toast('Listing link copied.')}else{openModal(`<span class="eyebrow">SHARE LISTING</span><h2>Copy this link</h2><input id="shareUrl" readonly value="${escapeHtml(share.url)}"><button class="auth-button primary" id="copyShareUrl">Copy link</button>`);$('#copyShareUrl').onclick=async()=>{const input=$('#shareUrl');input.select();document.execCommand('copy');closeModal();toast('Listing link copied.')}}}catch(error){if(error.name!=='AbortError')toast('Could not share this listing.')}}
function listingReportModal(item){if(!user){loginModal();toast('Sign in to report a listing.');return}openModal(`<span class="eyebrow">SAFETY REPORT</span><h2>Report this listing</h2><p>${escapeHtml(item.title)}</p><form id="reportForm"><label class="field-label">Why are you reporting it?</label><select name="reason"><option value="scam">Possible scam</option><option value="counterfeit">Counterfeit or misleading</option><option value="wrong_information">Incorrect information</option><option value="prohibited_item">Prohibited item</option><option value="other">Other concern</option></select><label class="field-label">Details (optional)</label><textarea name="details" rows="3" maxlength="1000" placeholder="Add context to help our safety team review it"></textarea><button class="auth-button primary">Submit report</button></form><p class="auth-note">Reports are for safety review. Do not include personal or payment details.</p>`);$('#reportForm').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.target),report={listingId:item.id,reason:String(form.get('reason')),details:String(form.get('details')||'').trim(),createdAt:new Date().toISOString()};if(isRealUser()&&item.user_id){const {error}=await sbClient.from('listing_reports').insert({reporter_id:user.id,listing_id:item.id,reason:report.reason,details:report.details});if(error){toast(`Could not submit report: ${error.message}`);return}}else{const reports=localArray('reports');reports.unshift(report);writeLocal('reports',JSON.stringify(reports))}closeModal();toast(isRealUser()&&item.user_id?'Report sent to the safety team.':'Report saved on this device for review.') }}
function openSharedListing(){const id=new URLSearchParams(location.search).get('listing');if(id&&listings.some(item=>item.id===id))listingModal(id)}
function filterModal(){openModal(`<span class="eyebrow">FIND YOUR KIND OF GOOD</span><h2>More filters</h2><p>Choose a category and optional maximum price.</p><div class="filter-modal-options">${categories.map(([name])=>`<label><input type="radio" name="filterCategory" value="${name}" ${activeCategory===name?'checked':''}> ${name}</label>`).join('')}<label><input type="radio" name="filterCategory" value="all" ${activeCategory==='all'?'checked':''}> All categories</label></div><label class="field-label">Maximum price</label><input id="maxPrice" type="number" min="0" placeholder="Any price" value="${priceLimit||''}"><button class="auth-button primary" id="applyFilters">Show finds</button>`);$('#applyFilters').onclick=()=>{activeCategory=$('input[name="filterCategory"]:checked')?.value||'all';priceLimit=Number($('#maxPrice').value)||0;favoritesOnly=false;renderListings();closeModal();$('#latest').scrollIntoView({behavior:'smooth'});toast(`${$('#resultsCount').textContent} match your filters.`)}}
function renderSearch(){favoritesOnly=false;activeCategory='all';query=$('#searchInput').value.trim();renderListings();$('#latest').scrollIntoView({behavior:'smooth'})}
