function applyLanguage(language){const useMl=language==='ml';document.documentElement.lang=useMl?'ml':'en';$('#languageSelect').value=useMl?'ml':'en';$('#searchInput').placeholder=useMl?'കാറുകൾ, ഫോണുകൾ എന്നിവ തിരയുക…':'Find cars, mobile phones and more...';for(const [selector,english] of Object.entries({'.filter-chip[data-filter="all"]':'All listings','.filter-chip[data-filter="Cars"]':'Cars','.filter-chip[data-filter="Mobiles"]':'Mobiles','.filter-chip[data-filter="Property"]':'Property','.filter-chip[data-filter="Furniture"]':'Home & living','.category-nav .all-cats':'ALL CATEGORIES ⌄','.category-nav a[data-category="Cars"]':'Cars','.category-nav a[data-category="Motorcycles"]':'Motorcycles','.category-nav a[data-category="Mobiles"]':'Mobiles','.category-nav a[data-category="Property"]':'For sale: Houses & Apartments','.category-nav a[data-category="Electronics"]':'Electronics','.category-nav a[data-category="Furniture"]':'Furniture','.category-nav a[data-category="Jobs"]':'Jobs','.welcome-strip b':'Good things find a new home.','.welcome-strip div span:not(.live-dot)':'A little less waste. A lot more good finds.','#locationPrompt':'Set your location →','.hero-copy .eyebrow':'A MARKETPLACE FOR SECOND CHANCES','.hero-copy h1':'Good things<br><em>go again.</em>','.hero-copy p':'Discover pre-loved finds from your community, or pass something good along.','#exploreBtn':'Explore listings ↗','.category-section .eyebrow':'BROWSE YOUR WAY','.category-section h2':'What are you looking for?','#allCategoriesBtn':'View all categories →','.feature-copy .eyebrow':'HAVE SOMETHING TO SELL?','.feature-copy h2':'One person’s “meh”<br>is another’s <em>must-have.</em>','.feature-copy p':'Turn the things you don’t need into cash. It takes less than a minute.','#bannerSell':'Post your ad ↗','.listing-heading .eyebrow':'FRESH FROM YOUR COMMUNITY','.listing-heading h2':'Fresh finds, just listed','#filterMore':'＋ More filters','#saveSearchBtn':'♡ Save search','#loadMore':'Show more listings ↓','.app-promo .eyebrow':'GOOD THINGS, KEPT MOVING','.app-promo h2':'Find something lovely.<br>Give it another life.','.app-promo p':'Browse local listings, save your finds, and chat with sellers right here.','#promoExplore':'Explore the marketplace ↗','footer .footer-top p':'Making second-hand feel first-class.','footer .footer-top div:nth-child(2) b':'Explore','footer .footer-top div:nth-child(3) b':'About redo','footer .footer-top div:nth-child(4) b':'Stay in the loop','footer .footer-top div:nth-child(4) p':'Good finds are better when shared.','footer .footer-top div:nth-child(2) a:nth-of-type(1)':'All categories','footer .footer-top div:nth-child(2) a:nth-of-type(2)':'Popular searches','footer .footer-top div:nth-child(2) a:nth-of-type(3)':'Nearby listings','footer .footer-top div:nth-child(3) a:nth-of-type(1)':'About us','footer .footer-top div:nth-child(3) a:nth-of-type(2)':'Careers','footer .footer-top div:nth-child(3) a:nth-of-type(3)':'Contact','#socialBtn':'Made for good finds ↗'})){const el=$(selector);if(el)el.innerHTML=useMl?(malayalamCopy[selector]||english):english}renderCategories()}
function initPreferences(){const savedTheme=readLocal('theme')||'light';document.documentElement.dataset.theme=savedTheme;$('#themeToggle').textContent=savedTheme==='dark'?'☀':'◐';$('#themeToggle').setAttribute('aria-label',savedTheme==='dark'?'Switch to light mode':'Switch to dark mode');$('#themeToggle').onclick=()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;writeLocal('theme',theme);$('#themeToggle').textContent=theme==='dark'?'☀':'◐';$('#themeToggle').setAttribute('aria-label',theme==='dark'?'Switch to light mode':'Switch to dark mode')};$('#languageSelect').onchange=()=>{writeLocal('language',$('#languageSelect').value);applyLanguage($('#languageSelect').value)};applyLanguage(readLocal('language')||'en')}
function bindEvents(){
  window.addEventListener('popstate',event=>{if(event.state?.redoChat&&chatContext){chatBackPushed=true;openChat(chatContext.listing,chatContext.thread,chatReturnTarget,true);return}if(chatBackPushed)handleChatBack(true)});
  const setMobileTab=id=>$$('.mobile-tab').forEach(button=>{const active=button.id===id;button.classList.toggle('active',active);if(active)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current')});
  $('#mobileHome').onclick=()=>{setMobileTab('mobileHome');window.scrollTo({top:0,behavior:'smooth'})};
  $('#mobileChats').onclick=()=>{setMobileTab('mobileChats');messagesModal()};
  $('#mobileSell').onclick=()=>{setMobileTab('mobileSell');sellModal()};
  $('#mobileMyAds').onclick=()=>{setMobileTab('mobileMyAds');if(isRealUser())myListingsModal();else loginModal()};
  $('#mobileAccount').onclick=()=>{setMobileTab('mobileAccount');if(isRealUser())openSettings('profile');else loginModal()};
  $('#searchBtn').onclick=renderSearch;$('#searchInput').addEventListener('keydown',e=>{if(e.key==='Enter')renderSearch()});$('#saveSearchBtn').onclick=saveCurrentSearch;
  $('#sellBtn').onclick=sellModal;$('#bannerSell').onclick=sellModal;$('#loginBtn').onclick=loginModal;$('#exploreBtn').onclick=()=>$('#latest').scrollIntoView({behavior:'smooth'});$('#loadMore').onclick=()=>{showAll=true;renderListings()};$('#sortSelect').onchange=renderListings;
  $('#listView').onclick=()=>{$('#listView').classList.add('active');$('#gridView').classList.remove('active');renderListings()};$('#gridView').onclick=()=>{$('#gridView').classList.add('active');$('#listView').classList.remove('active');renderListings()};$('#filterMore').onclick=filterModal;$('#allCategoriesBtn').onclick=()=>$('.category-section').scrollIntoView({behavior:'smooth'});
  $('#clearFilters').onclick=()=>{favoritesOnly=false;query='';locationQuery='';priceLimit=0;$('#searchInput').value='';updateLocationLabel('Kerala');setCategory('all')};
  $('#favoritesBtn').onclick=()=>{favoritesOnly=true;query='';$('#searchInput').value='';activeCategory='all';renderListings();$('#latest').scrollIntoView({behavior:'smooth'});if(!favorites.size)toast('Tap a heart on a listing to save it here.')};$('#messagesBtn').onclick=messagesModal;
  $('#locationSelect').onclick=openLocation;$('#locationPrompt').onclick=openLocation;$('.all-cats').onclick=()=>$('.category-section').scrollIntoView({behavior:'smooth'});
  $('#promoExplore').onclick=()=>$('#latest').scrollIntoView({behavior:'smooth'});

  $('#socialBtn').onclick=shareRedo;
  $$('[data-page]').forEach(link=>link.onclick=e=>{e.preventDefault();footerAction(link.dataset.page)});

  $$('.filter-chip').forEach(button=>button.onclick=()=>{query='';priceLimit=0;$('#searchInput').value='';setCategory(button.dataset.filter)});
  document.addEventListener('click',event=>{const category=event.target.closest('[data-category]');if(category){event.preventDefault();setCategory(category.dataset.category)}const favorite=event.target.closest('[data-fav]');if(favorite){event.stopPropagation();toggleFavorite(favorite.dataset.fav);return}const card=event.target.closest('.listing-card');if(card)listingModal(card.dataset.id)});
  $('#closeModal').onclick=closeModal;$('#modalBackdrop').onclick=event=>{if(event.target===$('#modalBackdrop')&&(!$('.welcome-auth-modal')||!$('#closeModal').hidden))chatBackPushed?handleChatBack():closeModal()};document.addEventListener('keydown',event=>{if(event.key==='Escape'&&(!$('.welcome-auth-modal')||!$('#closeModal').hidden))chatBackPushed?handleChatBack():closeModal()});
}
function setupMotion(){if(window.matchMedia('(prefers-reduced-motion: reduce)').matches||!('IntersectionObserver'in window))return;document.documentElement.classList.add('motion-on');const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('motion-visible');observer.unobserve(entry.target)}}),{threshold:.12,rootMargin:'0px 0px -24px 0px'});window.redoRevealObserver=observer;window.redoObserveReveal=nodes=>nodes.forEach((node,index)=>{if(node.dataset.revealReady)return;node.dataset.revealReady='1';node.classList.add('motion-reveal');node.style.setProperty('--reveal-delay',`${Math.min(index*45,270)}ms`);observer.observe(node)});window.redoObserveReveal($$('.welcome-strip,.hero,.category-section,.feature-banner,.listings-section,.app-promo,.footer-top'))}
async function initialize(){setupMotion();renderCategories();renderListings();bindEvents();initPreferences();updateLocationLabel('Kerala');const requireChoice=!sessionStorage.getItem('redo_guest_session');if(requireChoice)welcomeModal({required:true});if(!sbClient){if(!requireChoice)openSharedListing();return}let data;try{({data}=await sbClient.auth.getSession())}catch(error){toast(`Could not check sign-in status: ${error.message}`);return}await syncUser(data.session?.user||null);if(data.session?.user){if(requireChoice)closeModal();openSharedListing()}else if(!requireChoice)openSharedListing();sbClient.auth.onAuthStateChange((_event,session)=>{setTimeout(async()=>{await syncUser(session?.user||null);if(session?.user&&$('.welcome-auth-modal')){closeModal();openSharedListing()}},0)})}
initialize().catch(error=>{console.error(error);toast(`Marketplace could not finish loading: ${error.message}`)});
